const ICODEL='<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18"/><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/></svg>';
const ICOIMP='<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 5v14"/><path d="M19 12l-7 7-7-7"/></svg>';
const ICOEXP='<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 19V5"/><path d="M5 12l7-7 7 7"/></svg>';
$('tabs').addEventListener('wheel',e=>{const t=$('tabs');if(t.scrollWidth<=t.clientWidth||Math.abs(e.deltaX)>Math.abs(e.deltaY))return;t.scrollLeft+=e.deltaY;e.preventDefault()},{passive:false});      // 14.60: on a PC the wheel scrolls the tabs sideways (the drag is in the group below)
$('tabs').addEventListener('scroll',()=>{const t=$('tabs');t.classList.add('sc');clearTimeout(t._st);t._st=setTimeout(()=>t.classList.remove('sc'),900)},{passive:true});
function tabVis(el){const s=$('tabs');if(!el||!s)return;const r=el.getBoundingClientRect(),q=s.getBoundingClientRect(),R=42;if(r.right>q.right-R)s.scrollLeft+=r.right-(q.right-R);else if(r.left<q.left)s.scrollLeft-=q.left-r.left}      // keeps a tab / the name box clear of the pinned + button
function drawTabs(){
  drawMenu();
  if(XPM=='exp'&&XTAB!==tabs[active]){XPM=null;drawXP()}      // the export text belongs to the tab it was made in
  const tools=delPending
    ?`<span class="nb">Delete "${esc(tabs[active].name)}"?</span><button class="tl" data-act="yes">Yes, delete</button><button class="tl" data-act="no">Cancel</button>`
    :`<button class="tli" data-act="ren" aria-label="Rename" title="Rename">${ICOREN}</button><button class="tli" data-act="dup" aria-label="Duplicate" title="Duplicate">${ICODUP}</button>${tabs.length>1?`<button class="tli" data-act="del" aria-label="Delete" title="Delete">${ICODEL}</button>`:''}<button class="tli${XPM=='imp'?' on':''}" data-act="imp" aria-label="Import" title="Paste exported text: it opens as a new tab">${ICOIMP}</button><button class="tl${XPM=='exp'?' on':''}" data-act="exp" title="Show all inputs of this tab as text, to copy">${ICOEXP}Export</button>`;
  $('tabs').innerHTML='<div id="tabsin">'+tabs.map((t,i)=>`<button class="tab${i==active?' on':''}" data-t="${i}" title="${esc(t.name)} - double-click to rename">${esc(t.name)}</button>`).join('')+'<button type="button" class="tab add" id="tabadd" data-add="1" title="New tab">+</button></div>';
  $('tabtools').innerHTML=tools;tabVis(document.querySelector('#tabs .tab.on'));
}
function newName(){let n=tabs.length+1;while(tabs.some(t=>t.name==='Tab '+n))n++;return 'Tab '+n}
function switchTab(i){if(i==active)return;save();active=i;delPending=false;load(tabs[i].data);drawTabs();refresh()}
function addTab(){save();tabs.push({name:newName(),data:clone(BLANK)});active=tabs.length-1;delPending=false;load(tabs[active].data);drawTabs();refresh()}
function dupTab(){save();const src=tabs[active];tabs.splice(active+1,0,{name:src.name+' copy',data:clone(src.data)});active++;delPending=false;drawTabs();refresh()}
function delTab(){tabs.splice(active,1);active=Math.min(active,tabs.length-1);delPending=false;load(tabs[active].data);drawTabs();refresh()}
function rename(i){
  const b=document.querySelector(`.tab[data-t="${i}"]`);if(!b)return;
  const inp=document.createElement('input');inp.type='text';inp.className='tabin';inp.value=tabs[i].name;inp.maxLength=24;
  b.replaceWith(inp);inp.focus({preventScroll:true});inp.select();tabVis(inp);
  let done=false;
  const fin=ok=>{if(done)return;done=true;if(ok){const n=inp.value.trim();if(n)tabs[i].name=n}drawTabs();if(ready){const t=$('rtitle');if(t)t.textContent='Calculation — '+tabs[active].name}save()};
  inp.addEventListener('keydown',e=>{if(e.key=='Enter')fin(true);else if(e.key=='Escape')fin(false)});
  inp.addEventListener('blur',()=>fin(true));
}
function tabClick(e){
  const t=e.target.closest('[data-t]');
  if(t){switchTab(+t.dataset.t);return true}
  if(e.target.closest('[data-add]')){addTab();return true}
  const a=e.target.closest('[data-act]');
  if(a){
    const k=a.dataset.act;
    if((k=='lpick'||k=='epick')&&!a.dataset.d){a.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('on',b===a));a.dataset.d='1';setTimeout(()=>a.click(),140);return}      // a choice window: the clicked item becomes the highlighted one at once (the old one loses it), then the window closes a moment later
    if(k=='ren')rename(active);
    else if(k=='dup')dupTab();
    else if(k=='del'){delPending=true;drawTabs()}
    else if(k=='yes')delTab();
    else if(k=='no'){delPending=false;drawTabs()}
    else if(k=='exp'||k=='imp'){XPM=XPM==k?null:k;XTAB=tabs[active];drawXP();drawTabs()}
    else if(k=='xcopy')xCopy();
    else if(k=='xread')xRead();
    else if(k=='xshot'){const f=$('xfile');if(f)f.click()}
    else if(k=='xclose'){XPM=null;drawXP();drawTabs()}
    else if(k=='mnt'){MM=!MM;drawMenu()}      // the menu button of a phone: the menu opens as a dropdown under the logo line
    else if(k=='acct'){AP=!AP;drawAP();drawTabs();if(AP&&!aSes())gLoad().catch(()=>{})}      // the Google library is fetched while the panel opens, so the Google window can open at once on the click
    else if(k=='help'){HP=true;drawHP();drawMenu()}      // the 1-on-1 help window
    else if(k=='hclose')hpShut();
    else if(k=='eopen'){EPM=true;drawEP()}
    else if(k=='eclose')epShut();
    else if(k=='lopen'){LGM=true;drawLG()}
    else if(k=='lclose')lgShut();
    else if(k=='lpick'){lgShut();if(window.i18nSet)window.i18nSet(a.dataset.l)}
    else if(k=='epick'){$('epic').value=a.dataset.e||'';{const pe=EPICS.find(x=>x.n==$('epic').value);$('mode').value='max';$('enemy').value=pe&&!pe.en.includes(4)?String(pe.en[pe.en.length-1]):'4';SO=[]}      // a new choice starts in the full-health mode: 4-stack (8-stack for Arachne), 4-stack with no epic
    epShut();$('epic').dispatchEvent(new Event('change',{bubbles:true}))}
    else if(k=='fclose')fmShut();
    else if(k=='fapply'){const fp=$('fmFood'),fr=$('fmRev'),ft=$('fmTemple');if(fp&&$('foodP'))$('foodP').value=fp.value;if(fr&&$('revm'))$('revm').value=fr.value;if(ft&&$('temple'))$('temple').value=ft.value;fmShut(true);calc()}
    else if(k=='hcopy')hCopy();
    else if(k=='agoog')aGoogle();
    else if(k=='aclose'){AP=false;drawAP();drawTabs()}
    else if(k=='adbg'){DBGWANT=!DBGWANT;try{localStorage.setItem('krappy_debug',DBGWANT?'1':'0')}catch(e){}syncDebug();drawAP();calc()}
    else if(k=='aul'){ADM.open=!ADM.open;ADM.err='';drawAP();if(ADM.open)aUsers()}
    else if(k=='aview')aView(a.dataset.u);
    else if(k=='aexit')impExit();
    else if(k=='ain')aSign('signInWithPassword');
    else if(k=='aup')aSign('signUp');
    else if(k=='arst')aReset();
    else if(k=='aout'){impExit(true);aSet(null);SY.tok=null;SY.st='';SY.err=false;SY.conf=null;SY.pf=false;SY.role='';SY.hasRole=true;ADM.open=false;ADM.list=null;AM='in';AP=false;drawAP();drawTabs()}      // the tabs stay in this browser
    else if(k=='amup'){AM='up';drawAP()}
    else if(k=='amin'){AM='in';drawAP()}
    else if(k=='anm')aRename();
    else if(k=='async')syncNow();
    else if(k=='aboth'||k=='aacct'||k=='ahere')aChoose(k.slice(1));
    return true;
  }
  return false;
}
// ---- export / import: every input of the open tab as a short text, and back. An import opens as a NEW tab: nothing that is already saved is overwritten ----
// The text: a title line, then  key=value  pieces (one space between them). A box that holds the blank value (0) is left out, a number has no thousands commas, a space in a name is _ ; the key is short:
// L Leadership, U Authority, D Dominance, F Food prod., R Revive, Tp Temple level (13.1; left out when it is 45), A Action; hG / sG = health / strength bonus of Guardsmen (S, M, E, and Gi El Dr Be Me Mo Ra Fl Ep Pl the same way), dGi = Double strike; T = the ticked tiers (E89S89G89M789 = E8 E9 S8 S9 G8 G9 M7 M8 M9);
// n = name, x = switched-off troops (3 characters each, see xcode), at = Attack players, mo / en / le / lp = attack mode. Text of the first version (JSON, "Stack Calculator inputs") is still read.
const XMODES=['max','ren','ovo','pvpmax','cpd','cp','kill','kill4'],XENEMY=['3','4','6','8'],XHEAD='Krappy Calculator',XFIX={capA:'L',capU:'U',capM:'D',foodP:'F',revm:'R',shw:'A',temple:'Tp',renLv:'Lv',epic:'E'},XSUF={Epic:'Ep',Players:'Pl',Giant:'Gi',Elemental:'El',Dragon:'Dr',Beast:'Be',Melee:'Me',Mounted:'Mo',Ranged:'Ra',Flying:'Fl',Scout:'Sc',EMH:'EM'};
const xkey=id=>{const m=/^(bh|bs|dh)_(.+)$/.exec(id);return XFIX[id]||(m?{bh:'h',bs:'s',dh:'d'}[m[1]]+(XSUF[m[2]]||m[2]):id)};      // bh_G -> hG, bs_G -> sG, dh_Giant -> dGi, bs_Epic -> sEp
const xep=n=>String(n).slice(0,3).toLowerCase(),xepn=c=>{const e=EPICS.find(q=>q.n===c)||EPICS.find(q=>xep(q.n)==String(c).slice(0,3).toLowerCase());return e?e.n:c};      // 20.5.1: the epic in the export is its first 3 letters (arm = Armageddon/Basilisk); the full name of an older export is still read
const xhash=q=>{let h=2166136261;for(let i=0;i<q.length;i++){h^=q.charCodeAt(i);h=Math.imul(h,16777619)>>>0}return h};
const xcode=nm=>(xhash(nm)%46656).toString(36).padStart(3,'0');      // a troop (or mercenary) as 3 characters 0-9a-z: from its name, so it does not depend on the order of the tables; no two names of today share a code
let XMAP=null;
const xmap=()=>{if(XMAP)return XMAP;const m={};[...TR.map(t=>t.name),...MERC.map(q=>q[2]),...MERC_LATER.map(q=>q[2])].forEach(n=>{const c=xcode(n);if(m[c]&&m[c]!==n)console.warn('troop code clash',c,m[c],n);else m[c]=n});return XMAP=m};
let XPM=null,XTAB=null;      // the open panel: 'exp' (export), 'imp' (import) or null; XTAB = the tab an export was made in
function exportText(){
  const d=snap(),t=['n='+tabs[active].name.replace(/ /g,'_')],num=id=>$(id).matches(NUMBOX),val=(id,x)=>num(id)?String(x).replace(/,/g,''):String(x);
  for(const [id,x] of Object.entries(d.vals)){const w=id=='epic'?xep(x):val(id,x);if(w!==val(id,BLANK.vals[id]))t.push(xkey(id)+'='+w)}
  let T='';for(const c of 'ESGM'){let q='';for(let i=1;i<=9;i++)if(d.chk['s'+c+i])q+=i;if(q)T+=c+q}
  t.push('T='+T);
  for(const [id,c] of Object.entries(d.chk))if(!/^s[ESGM]\d$/.test(id)&&c!==BLANK.chk[id])t.push(id+'='+(c?1:0));      // any other tick box (none now)
  {const dx=BLANK.X||[];if(d.X.length!==dx.length||d.X.some(n=>!dx.includes(n)))t.push('x='+(d.X.length?d.X.map(xcode).join(''):'-'))}      // only when it differs from a new tab (x=- : nothing switched off)      // 3 characters per switched-off troop (the first versions wrote the names, they are still read)
  if(d.atk=='players')t.push('at=p');
  if(d.mode!='max')t.push('mo='+d.mode);
  if(d.enemy!='4')t.push('en='+d.enemy);
  if(d.le.mode!='max'||d.le.enemy!='4')t.push('le='+d.le.mode+':'+d.le.enemy);
  if(d.lp!='cp')t.push('lp='+d.lp);
  return XHEAD+' v'+APP_VERSION.split('.').slice(0,2).join('.')+'\n'+t.join(' ')+'\n';
}
function drawXP(){
  const p=$('xp');p.hidden=!XPM;if(!XPM){p.innerHTML='';return}
  const ex=XPM=='exp';
  p.innerHTML=`<div class="mu">${ex?'All inputs of this tab as a short text. Copy it and keep it anywhere (a note, a chat); Import reads it back.':'Paste the exported text here. It opens as a new tab; your other tabs are not changed.'}</div><textarea id="xt" spellcheck="false" ${ex?'readonly':'placeholder="Paste the exported text here"'}></textarea><div class="xr">${ex?'<button class="tl" data-act="xcopy">Copy</button>':'<button class="tl" data-act="xread">Import</button>'+(SY.role=='admin'?'<button class="tl" data-act="xshot" title="Admin: a screenshot with the exported text on it (a chat, a note) is read and opened as a new tab">Import via screenshot</button><input type="file" id="xfile" accept="image/*" hidden>':'')}<button class="tl" data-act="xclose">Close</button><span class="mu" id="xmsg"></span></div>`;
  const t=$('xt');if(ex)t.value=exportText();t.focus();if(ex){t.select();t.scrollTop=0}
}
async function xCopy(){
  const t=$('xt');t.focus();t.select();let ok=false;
  try{await navigator.clipboard.writeText(t.value);ok=true}catch(e){try{ok=document.execCommand('copy')}catch(x){}}
  t.select();t.scrollTop=0;$('xmsg').textContent=ok?'Copied.':'Press Ctrl+C to copy (the text is selected).';
}
function parseKrappy(txt){      // the short text -> the same object the first (JSON) version read
  const m=txt.search(/Krappy Calculator/i);if(m<0)return null;
  const ids={};Object.keys(BLANK.vals).forEach(id=>{ids[xkey(id)]=id});ids.epic='epic';
  const r={vals:{},chk:{},got:0},tok=txt.slice(m).replace(/^Krappy Calculator\s*v?\S*/i,'').match(/\S+/g)||[];
  for(const tk of tok){
    const i=tk.indexOf('=');if(i<1)continue;const k=tk.slice(0,i),w=tk.slice(i+1);let ok=true;
    if(k=='n')r.name=w.replace(/_/g,' ');
    else if(k=='T'){const on=new Set();for(const g of w.matchAll(/([ESGM])(\d+)/g))for(const c of g[2])on.add('s'+g[1]+c);Object.keys(BLANK.chk).forEach(id=>{if(/^s[ESGM]\d$/.test(id))r.chk[id]=on.has(id)})}
    else if(k=='x')r.X=w=='-'?[]:/^[0-9a-z]+$/.test(w)?(w.match(/.{3}/g)||[]).map(c=>xmap()[c]).filter(Boolean):w.split(',').filter(Boolean).map(q=>q.replace(/_/g,' '));      // codes (lower case and digits only) or, as before, names
    else if(k=='at')r.atk=w=='p'?'players':'epics';
    else if(k=='mo')r.mode=w;
    else if(k=='en')r.enemy=w;
    else if(k=='lp')r.lp=w;
    else if(k=='le'){const q=w.split(':');r.le={mode:q[0],enemy:q[1]}}
    else if(Object.prototype.hasOwnProperty.call(ids,k))r.vals[ids[k]]=w;
    else if(Object.prototype.hasOwnProperty.call(BLANK.chk,k))r.chk[k]=w=='1';
    else ok=false;
    if(ok)r.got++;
  }
  return r;
}
function importText(txt){
  let r=parseKrappy(txt);
  if(!r){      // the first version: JSON between the first { and the last }
    const a=txt.indexOf('{'),b=txt.lastIndexOf('}');if(a<0||b<a)return{ok:false,msg:'No inputs found in the text.'};
    try{r=JSON.parse(txt.slice(a,b+1))}catch(e){return{ok:false,msg:'The text is incomplete or was changed: paste the whole exported text.'}}
    if(!r||typeof r!='object'||!r.vals||typeof r.vals!='object')return{ok:false,msg:'No inputs found in the text.'};
    r.got=Object.keys(r.vals).length;
  }
  if(!r.got)return{ok:false,msg:'No inputs found in the text.'};
  const d=clone(BLANK),list=x=>x.filter(q=>typeof q=='string'&&q.length<=40).slice(0,300),own=(o,k)=>Object.prototype.hasOwnProperty.call(o,k);
  let n=0;
  for(const [id,val] of Object.entries(r.vals)){      // only the boxes this page has; a box the text lacks keeps the blank value (0)
    const el=$(id);if(!el||!own(BLANK.vals,id)||MODE_IDS.includes(id)||!(typeof val=='string'||typeof val=='number'))continue;
    let x=String(val).slice(0,30);
    if(id=='epic')x=xepn(x);
    if(el.matches(NUMBOX))x=fmtInt(x)||'0';
    else if(id=='temple')x=tempNorm(x);
    else if(el.tagName=='SELECT'&&![...el.options].some(o=>o.value===x))continue;
    d.vals[id]=x;n++;
  }
  if(r.chk&&typeof r.chk=='object')for(const [id,c] of Object.entries(r.chk))if(own(BLANK.chk,id)&&typeof c=='boolean')d.chk[id]=c;
  d.O=[];for(const c of 'ESGM')for(let i=1;i<=9;i++)if(d.chk['s'+c+i])d.O.push(c+i);      // the kill order of the ticked tiers (the same as sync() builds it)
  if(Array.isArray(r.X))d.X=list(r.X);d.S=[];
  d.atk=r.atk=='players'?'players':'epics';
  d.mode=XMODES.includes(r.mode)?r.mode:'max';d.enemy=XENEMY.includes(String(r.enemy))?String(r.enemy):'4';
  d.le=r.le&&typeof r.le=='object'&&XMODES.includes(r.le.mode)&&XENEMY.includes(String(r.le.enemy))?{mode:r.le.mode,enemy:String(r.le.enemy)}:{mode:'max',enemy:'4'};
  d.lp=['cp','cpd','ovo','pvpmax','ren'].includes(r.lp)?r.lp:'cp';
  let nm=typeof r.name=='string'&&r.name.trim()?r.name.trim().slice(0,24):'Imported';const base=nm;let k=2;
  while(tabs.some(t=>t.name===nm))nm=base.slice(0,20)+' '+k++;
  save();tabs.push({name:nm,data:d});active=tabs.length-1;delPending=false;load(d);drawTabs();refresh();
  return{ok:true,msg:'Read '+n+(n==1?' box':' boxes')+' - opened as the new tab “'+nm+'”.'};
}
function xRead(){
  const t=$('xt'),r=importText(t.value);
  if(r.ok)t.value='';
  $('xmsg').textContent=r.msg;
}

// ---- Import via screenshot (admin): a picture with the exported text on it is read in the browser (OCR: tesseract.js, loaded from a CDN only when this button is used), the text is cleaned up (the OCR mixes up the case of letters and adds stray marks) and opened like a pasted export ----
const OCRV={js:'https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js',lang:'https://cdn.jsdelivr.net/npm/@tesseract.js-data/eng@1.0.0/4.0.0_fast',lang2:'https://unpkg.com/@tesseract.js-data/eng@1.0.0/4.0.0_fast',worker:'https://cdn.jsdelivr.net/npm/tesseract.js@v5.1.1/dist/worker.min.js',local:'eng.traineddata.gz.b64.txt'};
let OCRW=null,OCRP=null;
// The English language data (tessdata_fast, gzipped, as base64 text) is the file next to this page: it is fetched here (the page may not be allowed to let the reader's worker download from a CDN) and the reader's worker is started from a small script that answers the worker's request for eng.traineddata.gz from this copy, then loads the real worker
function ocrWorkerUrl(b){
  const code='const B64="'+b+'";let GZ=null;const of=self.fetch;self.fetch=function(u){const x=String(u&&u.url?u.url:u);if(/traineddata/.test(x)){if(!GZ){const s=atob(B64),a=new Uint8Array(s.length);for(let i=0;i<s.length;i++)a[i]=s.charCodeAt(i);GZ=a}return Promise.resolve(new Response(GZ.slice(),{status:200}))}return of.apply(self,arguments)};importScripts("'+OCRV.worker+'");';
  return URL.createObjectURL(new Blob([code],{type:'text/javascript'}))}
function ocrLoad(){if(window.Tesseract)return Promise.resolve();
  return OCRP||(OCRP=new Promise((ok,no)=>{const s=document.createElement('script');s.src=OCRV.js;s.onload=()=>ok();s.onerror=()=>{OCRP=null;no(new Error('the reader could not be loaded (no connection to the CDN?)'))};document.head.appendChild(s)}))}
async function ocrRead(file,prog){await ocrLoad();
  if(!OCRW){      // the language data: from the file next to this page, when that is missing or fails from the CDN, then from the second CDN without the cache
    let b64=null;try{const r=await fetch(OCRV.local);if(r.ok)b64=(await r.text()).trim()}catch(e){}
    const tries=[...(b64?[{lp:'https://ocr.invalid',c:'none',b:b64}]:[]),{lp:OCRV.lang},{lp:OCRV.lang2,c:'none'}];let last=null;
    for(const t of tries){let w=null,done=false;
      try{const o={langPath:t.lp,logger:m=>{if(prog&&m&&typeof m.progress=='number')prog(m.status,m.progress)},errorHandler:e=>{last=e}};if(t.c)o.cacheMethod=t.c;if(t.b){o.workerPath=ocrWorkerUrl(t.b);o.workerBlobURL=false}
        w=await Promise.race([Tesseract.createWorker('eng',1,o),new Promise((_,no)=>setTimeout(()=>{if(!done)no(new Error('timeout'))},40000))]);done=true;OCRW=w;break}
      catch(e){done=true;last=e;try{if(w)await w.terminate()}catch(x){}}}
    if(!OCRW)throw new Error('the language data could not be loaded (the network of this page may block it)'+(last&&last.message&&last.message!='timeout'?': '+last.message:''))}
  await OCRW.setParameters({tessedit_pageseg_mode:'4'});      // one column of text of different sizes
  const r=await OCRW.recognize(file);return r.data.text}
// The English language data of the reader is the file eng.traineddata.gz.b64.txt next to this page (tessdata_fast; 2.6 MB, fetched only when the screenshot import is used); the CDN is the fallback
// the OCR text -> the export text: the part from "Krappy Calculator" on, every key=value token with the key in its exact case (the OCR mixes sM / SM), digits that look like letters put right in the number boxes. Returns {text, n, bad: the tokens that are not sure, drop: the ones left out}
function ocrClean(raw){
  const keys={},num={};      // canonical keys; num = the keys of number boxes
  Object.keys(BLANK.vals).forEach(id=>{const k=xkey(id);keys[k]=1;if($(id)&&$(id).matches(NUMBOX))num[k]=1});
  ['n','T','x','at','mo','en','le','lp',...Object.keys(BLANK.chk).filter(k=>!/^s[ESGM]\d$/.test(k))].forEach(k=>keys[k]=1);
  const low={};Object.keys(keys).forEach(k=>(low[k.toLowerCase()]=low[k.toLowerCase()]||[]).push(k));
  const canon=k=>keys[k]?k:(low[k.toLowerCase()]&&low[k.toLowerCase()].length==1?low[k.toLowerCase()][0]:null);
  let t=String(raw||'');const m=t.search(/k\w{0,2}appy\s*c\w{0,3}[il1]cul\w{2,4}/i),m2=m<0?t.search(/alculator/i):m;
  let ver='';if(m2>=0){const h=t.slice(m2).split('\n')[0].match(/v\s*(\d+[.,]\d+)/i);ver=h?h[1].replace(',','.'):'';t=t.slice(m2).split('\n').slice(1).join(' ')}
  const out=[],bad=[],drop=[];
  for(const tk of t.match(/\S+/g)||[]){
    const i=tk.indexOf('=');if(i<1)continue;
    const k0=tk.slice(0,i).replace(/^[^A-Za-z]+/,''),k=canon(k0);let w=tk.slice(i+1).replace(/[|\[\]{}()<>,;:]+$/,'');
    if(!k){drop.push(tk);continue}
    if(num[k]){const f=w.replace(/[Oo]/g,'0').replace(/[lI|!]/g,'1').replace(/[Ss]/g,'5').replace(/B/g,'8').replace(/[^0-9.]/g,'');if(/^\d+(\.\d+)?$/.test(f)){if(f!==w)bad.push(k+'='+f+' (read as '+w+')');w=f}else bad.push(tk)}
    else if(k=='T'){const f=w.toUpperCase().replace(/[^ESGM1-9]/g,'');if(!/^([ESGM][1-9]+)+$/.test(f))bad.push(tk);w=f||w}
    out.push(k+'='+w)}
  return{text:'Krappy Calculator v'+(ver||APP_VERSION.split('.').slice(0,2).join('.'))+'\n'+out.join(' ')+'\n',n:out.length,bad,drop}}
async function xShot(file){
  const msg=t=>{const e=$('xmsg');if(e)e.textContent=t},box=$('xt');
  if(SY.role!='admin')return;
  try{msg('Reading the picture ... (the first time the reader is loaded: a few MB)');
    const raw=await ocrRead(file,(s,p)=>msg('Reading the picture ... '+(s||'')+' '+Math.round(p*100)+'%')),c=ocrClean(raw);
    if(!c.n){msg('No exported text found in the picture. Is the whole text visible (the line Krappy Calculator and the lines under it)?');return}
    if(box)box.value=c.text;
    const r=importText(c.text);if(r.ok&&box)box.value='';
    msg((r.ok?r.msg+' ':'')+(r.ok?'':r.msg+' ')+'Check it against the picture.'+(c.bad.length?' Not sure: '+c.bad.join(', ')+'.':'')+(c.drop.length?' Left out: '+c.drop.join(', ')+'.':''))
  }catch(e){msg('Could not read the picture'+(e&&e.message?': '+e.message:'.'))}}

// ---- account (10.1): e-mail + password sign-in; the tabs are kept on the account and open on every device ----
// The page talks straight to Firebase's web API, no library: Identity Toolkit for the sign-in, Firestore for ONE document per user (users/<uid>, field "data" = all tabs as JSON; the Firestore rules let a user read and write only his own document).
// The password goes only to Google's sign-in service and is never stored; the browser keeps a refresh token (localStorage key sc_acct). With FB.key empty the whole feature is off: no button, no network.
// A saved tab is never overwritten without a choice: syncNow pushes this browser's changes, takes the account's tabs only when this browser has no changes of its own, and asks (keep both / account / this browser) when both changed.
const FB={key:'AIzaSyCWQWxkwjaWnZ-AmLi6pmfosrbD5gp0m58',project:'krappycalculator'};      // key = the Web API key of the Firebase project (public by design)
const AKEY='sc_acct';
let AP=false,APO=false,MM=false,HP=false,AM='in',ADM={open:false,list:null,busy:false,st:'',err:'',q:''},SY={role:'',hasRole:true,rt:0,pf:false,busy:false,t:0,st:'',err:false,conf:null,tok:null,exp:0,at:0};      // AP = the account panel is open; SY = the sync state (st = the text shown, conf = a conflict that waits for the user's choice, tok / exp = the id token and when it runs out)
const aSes=()=>{try{const s=JSON.parse(localStorage.getItem(AKEY)||'null');return s&&s.rt&&s.uid?s:null}catch(e){return null}};
const aRec=()=>{try{return JSON.parse(localStorage.getItem('sc_acct_rec')||'{}')||{}}catch(e){return{}}};      // per account: the version and the hash of this browser's tabs at the last sync; it survives a sign-out, so a later sign-in knows what changed since
const aSet=s=>{try{if(s)localStorage.setItem(AKEY,JSON.stringify(s));else localStorage.removeItem(AKEY)}catch(e){}};
const FBMSG={EMAIL_EXISTS:'This e-mail already has an account: use Sign in.',INVALID_LOGIN_CREDENTIALS:'Wrong e-mail or password.',INVALID_PASSWORD:'Wrong e-mail or password.',EMAIL_NOT_FOUND:'Wrong e-mail or password.',WEAK_PASSWORD:'The password needs at least 6 characters.',INVALID_EMAIL:'This e-mail address is not valid.',MISSING_PASSWORD:'Enter the password.',MISSING_EMAIL:'Enter the e-mail.',USER_DISABLED:'This account is switched off.',TOO_MANY_ATTEMPTS_TRY_LATER:'Too many tries. Wait a little and try again.',OPERATION_NOT_ALLOWED:'E-mail sign-in is not switched on in the Firebase project (Authentication, Sign-in method).',PERMISSION_DENIED:'The account database refused the access (check the Firestore rules).',INVALID_REFRESH_TOKEN:'The sign-in has run out: sign in again.',TOKEN_EXPIRED:'The sign-in has run out: sign in again.',USER_NOT_FOUND:'The sign-in has run out: sign in again.'};
async function fbCall(url,opt){
  let r;try{r=await fetch(url,opt)}catch(e){throw Object.assign(new Error('No connection to the account service.'),{code:'NETWORK'})}
  let j=null;try{j=await r.json()}catch(e){}
  if(!r.ok){const raw=String(j&&j.error&&(j.error.message||j.error.status)||r.status),c=raw.split(/[ :]/)[0];
    throw Object.assign(new Error(FBMSG[c]||FBMSG[j&&j.error&&j.error.status]||'The account service refused it ('+c+').'),{code:c,http:r.status,st:j&&j.error&&j.error.status,raw})}
  return j;
}
const AU='https://identitytoolkit.googleapis.com/v1/accounts:';
const aTok=(t,ex)=>{SY.tok=t;SY.exp=Date.now()+(Math.max(120,+ex||3600)-60)*1000};
async function aAuth(kind,email,pw){const j=await fbCall(AU+kind+'?key='+FB.key,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password:pw,returnSecureToken:true})});aTok(j.idToken,j.expiresIn);return j}
async function aToken(){
  const s=aSes();if(!s)throw Object.assign(new Error('Not signed in.'),{code:'NOSES'});
  if(SY.tok&&Date.now()<SY.exp)return SY.tok;
  const j=await fbCall('https://securetoken.googleapis.com/v1/token?key='+FB.key,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'grant_type=refresh_token&refresh_token='+encodeURIComponent(s.rt)});
  aTok(j.id_token,j.expires_in);if(j.refresh_token&&j.refresh_token!==s.rt){s.rt=j.refresh_token;aSet(s)}
  return SY.tok;
}
const FS=uid=>'https://firestore.googleapis.com/v1/projects/'+FB.project+'/databases/(default)/documents/users/'+encodeURIComponent(uid);
async function fsGet(tok,uid){
  try{const j=await fbCall(FS(uid),{headers:{Authorization:'Bearer '+tok}}),f=j.fields||{},v=k=>(f[k]&&f[k].stringValue)||'';return{exists:true,str:v('data'),rev:j.updateTime,role:v('role'),name:v('name'),email:v('email')}}
  catch(e){if(e.http==404&&/document .* not found/i.test(e.raw||''))return{exists:false};if(e.http==404)e.message='The Firestore database is not created yet (Firebase console, Firestore Database, Create database).';throw e}
}
async function fsPut(tok,uid,str,rev){      // rev = the version this browser last saw: the save is refused when the account changed since (a conflict), so nothing is overwritten by accident. str = null: only the profile fields are written
  if(str&&str.length>900000)throw Object.assign(new Error('The tabs are too big for the account (limit about 900 KB).'),{code:'BIG'});
  const s=aSes()||{},f={name:{stringValue:s.name||''},email:{stringValue:s.email||''}},m=['name','email'];      // the name and the e-mail are also kept in the document, so the admin's user list (and the Firebase console) can show who it is
  if(str!==null){f.data={stringValue:str};m.unshift('data')}
  if(!SY.hasRole){f.role={stringValue:'user'};m.push('role')}      // a document without a role gets the default one; an existing role (admin, set in the Firebase console) is never written from here, the rules refuse a change anyway
  const pre=rev?'currentDocument.updateTime='+encodeURIComponent(rev):'currentDocument.exists=false';
  try{const j=await fbCall(FS(uid)+'?'+m.map(x=>'updateMask.fieldPaths='+x).join('&')+'&'+pre,{method:'PATCH',headers:{Authorization:'Bearer '+tok,'Content-Type':'application/json'},body:JSON.stringify({fields:f})});SY.hasRole=true;SY.role=SY.role||'user';return j.updateTime}
  catch(e){if(e.st=='FAILED_PRECONDITION'||e.st=='ABORTED'||e.st=='ALREADY_EXISTS'||e.http==409||e.http==412)e.conflict=true;throw e}
}
const aProfOk=r=>{const s=aSes();return !s||(r.name===(s.name||'')&&r.email===(s.email||'')&&!!r.role)};      // the document already holds the current name, e-mail and a role
const aPay=()=>JSON.stringify({v:1,active,tabs});
const aHash=()=>xhash(JSON.stringify(tabs));
function aParse(str){      // the account's text -> {tabs, active}, only well-formed tabs
  try{const o=JSON.parse(str);if(!o||!Array.isArray(o.tabs))return null;
    const t=o.tabs.filter(x=>x&&typeof x.name=='string'&&x.data&&typeof x.data=='object').slice(0,100).map(x=>({name:x.name.slice(0,24),data:x.data}));
    return t.length?{tabs:t,active:Math.min(Math.max(0,o.active|0),t.length-1)}:null}catch(e){return null}
}
const tabsBlank=()=>tabs.every(t=>JSON.stringify(t.data&&t.data.vals)===JSON.stringify(BLANK.vals)&&JSON.stringify(t.data&&t.data.chk)===JSON.stringify(BLANK.chk));      // every tab of this browser still holds the blank values: nothing of its own to lose
const aBak=()=>{try{localStorage.setItem('sc_tabs_bak',localStorage.getItem(KEY)||'')}catch(e){}};      // the tabs of this browser, once, before the account's tabs replace them
function aApply(rem){aBak();tabs=rem.tabs.map(t=>({name:t.name,data:t.data}));active=rem.active;delPending=false;load(tabs[active].data);drawTabs();refresh();save(true)}
function aMerge(rem){      // the account's tabs that this browser lacks are added (a tab with the same name and the same numbers is not added twice; the same name with other numbers gets "2", "3" ...)
  const have=new Set(tabs.map(t=>t.name+'\n'+JSON.stringify(t.data)));let n=0;
  for(const t of rem.tabs){if(have.has(t.name+'\n'+JSON.stringify(t.data)))continue;let nm=t.name,b=nm,k=2;while(tabs.some(x=>x.name===nm))nm=b.slice(0,20)+' '+k++;tabs.push({name:nm,data:t.data});n++}
  return n;
}
function aState(txt,err){SY.st=txt||'';SY.err=!!err;drawTabs();drawAP()}
function aDone(rev,h,txt){SY.rt=0;const s=aSes();if(s){s.rev=rev;s.h=h;aSet(s);const m=aRec();m[s.uid]={rev,h};try{localStorage.setItem('sc_acct_rec',JSON.stringify(m))}catch(e){}}SY.at=Date.now();aState(txt||'Saved to the account '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})+'.')}
const aName=s=>s.name||s.email;
const ALOST=['INVALID_REFRESH_TOKEN','TOKEN_EXPIRED','USER_NOT_FOUND','USER_DISABLED','UNAUTHENTICATED','NOSES'];
function aFail(e){
  if(e.code=='NETWORK')aState('Offline: the tabs stay in this browser and are saved to the account when the connection is back.',true);
  else if(ALOST.includes(e.code)){aSet(null);SY.tok=null;SY.st='';SY.err=false;SY.role='';SY.hasRole=true;AP=true;drawTabs();drawAP();aMsg('The sign-in has run out: sign in again. Your tabs are still here.')}
  else aState(e.message||'The sync failed.',true);
}
async function syncNow(){
  const s=aSes();if(!FB.key||!s||SY.busy||SY.conf||IMP)return;
  SY.busy=true;clearTimeout(SY.t);aState('Syncing…');
  try{
    save(true);      // the open tab's boxes go into tabs first
    const tok=await aToken();if(!SY.pf){await aProfile(tok);SY.pf=true}
    const r=await fsGet(tok,s.uid),lh=aHash();SY.role=r.role||'user';SY.hasRole=!!r.role;
    if(!r.exists)aDone(await fsPut(tok,s.uid,aPay(),null),lh);
    else if(s.rev&&r.rev===s.rev){if(lh!==s.h)aDone(await fsPut(tok,s.uid,aPay(),r.rev),lh);else if(!aProfOk(r))aDone(await fsPut(tok,s.uid,null,r.rev),lh);else aDone(r.rev,lh,SY.st&&/^Saved/.test(SY.st)?SY.st:'Up to date.')}      // the account did not change since the last sync
    else{      // the account changed (another device), or this browser has not synced yet
      const rem=aParse(r.str);if(!rem)throw Object.assign(new Error("The tabs on the account could not be read, so nothing was changed."),{code:'BAD'});
      if(xhash(JSON.stringify(rem.tabs))===lh)aDone(aProfOk(r)?r.rev:await fsPut(tok,s.uid,null,r.rev),lh);
      else if((s.rev&&lh===s.h)||tabsBlank()){aApply(rem);aDone(r.rev,aHash(),'Took the tabs of the account '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})+'.')}      // no changes of its own here: the account's tabs are taken
      else{SY.conf={rem,rev:r.rev};AP=true;aState('Your choice is needed: this browser and the account differ.',true)}      // both changed: the user chooses
    }
  }catch(e){if(e.conflict&&++SY.rt<4){SY.busy=false;setTimeout(syncNow,300);return}SY.rt=0;aFail(e)}
  finally{SY.busy=false;drawTabs();drawAP()}
}
async function aChoose(k){
  const c=SY.conf,s=aSes();if(!c||!s||SY.busy)return;SY.busy=true;
  try{
    const tok=await aToken();
    if(k=='both'){aBak();const n=aMerge(c.rem);save(true);SY.conf=null;drawTabs();aDone(await fsPut(tok,s.uid,aPay(),c.rev),aHash(),'Kept both: '+n+(n==1?' tab':' tabs')+' of the account added here, everything saved to the account.')}
    else if(k=='acct'){SY.conf=null;aApply(c.rem);aDone(c.rev,aHash(),"Using the account's tabs.")}
    else{save(true);SY.conf=null;aDone(await fsPut(tok,s.uid,aPay(),c.rev),aHash(),"This browser's tabs saved to the account.")}
  }catch(e){if(e.conflict&&++SY.rt<4){SY.conf=null;SY.busy=false;setTimeout(syncNow,300);return}SY.rt=0;aFail(e)}
  finally{SY.busy=false;drawTabs();drawAP()}
}
const aMsg=t=>{const m=$('amsg');if(m)m.textContent=t};
const aClean=n=>String(n||'').replace(/\s+/g,' ').trim().slice(0,24);
async function aSetName(name){      // the username is the display name of the Firebase account (not unique: it is only shown to its owner)
  const tok=await aToken();
  await fbCall(AU+'update?key='+FB.key,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idToken:tok,displayName:name,returnSecureToken:false})});
  const s=aSes();if(s){s.name=name;aSet(s)}
}
async function aProfile(tok){      // once per page load: the name (changed on another device?) and whether the account still exists
  try{const j=await fbCall(AU+'lookup?key='+FB.key,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idToken:tok})});
    const u=j&&j.users&&j.users[0],s=aSes();
    if(u&&s&&((u.displayName||'')!==(s.name||'')||(u.email&&u.email!==s.email))){s.name=u.displayName||'';if(u.email)s.email=u.email;aSet(s)}}
  catch(e){if(e.code=='NETWORK'||ALOST.includes(e.code))throw e}
}
async function aSign(kind){      // 'signInWithPassword' or 'signUp' (sign-up needs the username)
  const f=document.querySelector('#ap form');if(!f)return;const up=kind=='signUp',em=f.elements.aem.value.trim(),pw=f.elements.apw.value,un=up?aClean(f.elements.aun.value):'';
  if(up&&un.length<2){aMsg('Enter a username (2 to 24 characters), best your in-game name.');return}
  if(!em||!pw){aMsg('Enter the e-mail and the password.');return}
  aMsg('Please wait…');
  try{
    const j=await aAuth(kind,em,pw),rc=aRec()[j.localId]||{};
    aSet({rt:j.refreshToken,uid:j.localId,email:j.email||em,name:up?un:(j.displayName||''),rev:rc.rev||null,h:rc.h||null});
    SY.conf=null;SY.pf=true;AP=true;
    let nerr='';if(up){try{await aSetName(un)}catch(e){nerr='The account was created, but the username could not be saved ('+e.message+'). Set it in the account panel.';const q=aSes();if(q){q.name='';aSet(q)}}}
    await syncNow();drawAP();if(nerr)aMsg(nerr);else if(!SY.err&&!SY.conf)apShut()
  }catch(e){aMsg(e.message)}
}
async function aRename(){
  const f=document.querySelector('#ap form[data-f=nm]');if(!f||!aSes())return;const un=aClean(f.elements.aun.value);
  if(un.length<2){aMsg('A username has 2 to 24 characters.');return}
  aMsg('Saving…');
  try{await aSetName(un);drawTabs();drawAP();aMsg('Username saved.');syncNow()}catch(e){if(ALOST.includes(e.code))aFail(e);else aMsg(e.message)}
}
async function aReset(){
  const f=document.querySelector('#ap form');if(!f)return;const em=f.elements.aem.value.trim();if(!em){aMsg('Enter the e-mail first.');return}
  try{await fbCall(AU+'sendOobCode?key='+FB.key,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({requestType:'PASSWORD_RESET',email:em})});aMsg('If this e-mail has an account, a link to set a new password was sent.')}
  catch(e){aMsg(e.code=='EMAIL_NOT_FOUND'?'If this e-mail has an account, a link to set a new password was sent.':e.message)}
}

// Roles: every account is a "user" (the field role of its document); "admin" is set by the site owner in the Firebase console, the Firestore rules refuse any other change of it. An admin sees the list of the users and can open one user's tabs as a READ-ONLY view: they are held in memory (IMP), save() and the sync do nothing meanwhile, and "Back to my tabs" restores the admin's own tabs.
const FSL='https://firestore.googleapis.com/v1/projects/'+FB.project+'/databases/(default)/documents/users?pageSize=300&mask.fieldPaths=name&mask.fieldPaths=email&mask.fieldPaths=role';
async function aUsers(){      // admin: the list of the users (name, e-mail, role, last saved); the tabs themselves are not fetched here
  if(ADM.busy)return;ADM.busy=true;ADM.err='';drawUL();
  try{
    const tok=await aToken(),L=[];let pt='';
    for(let i=0;i<10;i++){
      const j=await fbCall(FSL+(pt?'&pageToken='+encodeURIComponent(pt):''),{headers:{Authorization:'Bearer '+tok}});
      (j.documents||[]).forEach(d=>{const f=d.fields||{},v=k=>(f[k]&&f[k].stringValue)||'';L.push({uid:decodeURIComponent(String(d.name).split('/').pop()),name:v('name'),email:v('email'),role:v('role')||'user',t:d.updateTime||''})});
      pt=j.nextPageToken||'';if(!pt)break;
    }
    const nm=u=>(u.name||u.email||u.uid).toLowerCase();ADM.list=L.sort((a,b)=>nm(a).localeCompare(nm(b)));
  }catch(e){if(ALOST.includes(e.code))aFail(e);else ADM.err=e.message}
  finally{ADM.busy=false;drawUL()}
}
function drawUL(){
  const b=$('aul');if(!b)return;const s=aSes(),q=ADM.q.trim().toLowerCase();
  const L=(ADM.list||[]).filter(u=>(!s||u.uid!==s.uid)&&(!q||(u.name+' '+u.email+' '+u.uid).toLowerCase().includes(q)));
  b.innerHTML=(ADM.busy&&!ADM.list?'<div class="mu">Loading…</div>':'')+(ADM.err?'<div class="mu er">'+esc(ADM.err)+'</div>':'')+(ADM.st?'<div class="mu">'+esc(ADM.st)+'</div>':'')
    +(L.length?L.map(u=>`<button class="tl urw" data-act="aview" data-u="${esc(u.uid)}" title="Open the saved tabs of this user (read-only)"><span><b>${esc(u.name||u.email||u.uid.slice(0,8))}</b>${u.role!='user'?'<i class="rl ad">'+esc(u.role)+'</i>':''}</span><span class="mu">${esc(u.name&&u.email?u.email+' · ':'')}saved ${u.t?esc(new Date(u.t).toLocaleDateString()):'-'}</span></button>`).join(''):ADM.list&&!ADM.busy?'<div class="mu">'+(q?'No user matches.':'No other users yet.')+'</div>':'');
}
function drawImp(){
  const b=$('imp');if(!b)return;
  if(!IMP){b.hidden=true;b.innerHTML='';return}
  b.hidden=false;b.innerHTML=`<span><b>Viewing ${esc(IMP.name)}</b>${IMP.email&&IMP.email!==IMP.name?' ('+esc(IMP.email)+')':''}: read-only, nothing you change here is saved.</span><button class="tl" data-act="aexit">← Back to my tabs</button>`;
}
async function aView(uid){
  const s=aSes(),u=(ADM.list||[]).find(x=>x.uid===uid);if(!s||!u||SY.busy||SY.conf||SY.role!='admin')return;
  const nm=u.name||u.email||u.uid.slice(0,8);SY.busy=true;ADM.err='';ADM.st='Opening the tabs of '+nm+'…';drawUL();
  try{
    const tok=await aToken(),r=await fsGet(tok,uid);
    if(!r.exists||!r.str)throw new Error('This user has no saved tabs yet.');
    const rem=aParse(r.str);if(!rem)throw new Error('The saved tabs of this user could not be read.');
    if(!IMP)save(true);      // the admin's own open tab goes into the admin's own tabs first
    const st=IMP?IMP.stash:{tabs,active};clearTimeout(SY.t);
    IMP={uid,name:nm,email:u.email,stash:st};
    tabs=rem.tabs.map(t=>({name:t.name,data:t.data}));active=rem.active;delPending=false;XPM=null;drawXP();load(tabs[active].data);
    ADM.st='';AP=false;drawAP();drawImp();drawTabs();refresh();window.scrollTo(0,0);
  }catch(e){ADM.st='';if(ALOST.includes(e.code))aFail(e);else ADM.err=e.message}
  finally{SY.busy=false;drawUL();drawTabs()}
}
function impExit(ns){      // back to the admin's own tabs (they were not touched); ns = no sync afterwards
  if(!IMP)return;const st=IMP.stash;IMP=null;tabs=st.tabs;active=st.active;delPending=false;XPM=null;drawXP();load(tabs[active].data);drawImp();drawTabs();refresh();if(!ns)syncNow();
}

// Google sign-in: the small Firebase library (loaded only when the sign-in panel opens) shows the Google window; its tokens then go into the same direct-API session as an e-mail sign-in, the library keeps no session of its own.
const FBSDK='https://www.gstatic.com/firebasejs/10.12.2/';
let GSDK=null;
const gLoad=()=>GSDK||(GSDK=Promise.all([import(FBSDK+'firebase-app.js'),import(FBSDK+'firebase-auth.js')]).then(([a,b])=>({a,b})).catch(e=>{GSDK=null;throw e}));
const GERR={'auth/popup-closed-by-user':'The Google window was closed before the sign-in was finished.','auth/popup-blocked':'The browser blocked the Google window: allow pop-ups for this page and try again.','auth/unauthorized-domain':'This website is not on the list of authorized domains of the Firebase project (Authentication, Settings, Authorized domains).','auth/operation-not-allowed':'Google sign-in is not switched on in the Firebase project (Authentication, Sign-in method).','auth/network-request-failed':'No connection to the account service.','auth/account-exists-with-different-credential':'This e-mail already has an account with a password: sign in with the password.','auth/cancelled-popup-request':''};
async function aGoogle(){
  aMsg('Opening Google…');
  let L;try{L=await gLoad()}catch(e){aMsg('Could not load the Google sign-in. Check the connection and try again.');return}
  try{
    const {a,b}=L,app=a.getApps().length?a.getApp():a.initializeApp({apiKey:FB.key,authDomain:FB.project+'.firebaseapp.com',projectId:FB.project}),auth=b.getAuth(app);
    const u=(await b.signInWithPopup(auth,new b.GoogleAuthProvider())).user,tok=await u.getIdToken(),uid=u.uid,rt=u.refreshToken,em=u.email||'Google account',nm=aClean(u.displayName);
    try{await b.signOut(auth)}catch(e){}
    aTok(tok,3600);const rc=aRec()[uid]||{};aSet({rt,uid,email:em,name:nm,rev:rc.rev||null,h:rc.h||null});
    SY.conf=null;SY.pf=true;AP=true;await syncNow();drawAP();if(!SY.err&&!SY.conf)apShut();
  }catch(e){const c=e&&e.code;aMsg(c in GERR?GERR[c]:'Google sign-in failed ('+(c||(e&&e.message)||'error')+').')}
}
