let apDn=null,inAmo=false;document.addEventListener('pointerdown',e=>{apDn=e.target;inAmo=!!(e.target.closest&&e.target.closest('.amo'))},true);document.addEventListener('click',()=>{setTimeout(()=>{inAmo=false},0)});
