      let H=Infinity,T=Infinity;[...ldm.filter(s=>s.n>0),...tl].sort((a,b)=>ix[a.name]-ix[b.name]).forEach(s=>{H=tot(s.n,s.hp);if(strRef(s))T=tot(s.n,s.str)});
