function brEnemy(P){if(P.one)return{name:'Corax II',ic:brImg('Corax II')};if(P.pm)return{name:'Full city',ic:BRCITY};if(P.ren)return{name:'Renegades',ic:''};const e=epCur();return e?{name:esc(e.n),ic:EPIC_FR[e.ic]?'<img class="ic2" src="'+EPIC_FR[e.ic]+'" alt="">':(epImg(e,'ic2')||'')}:{name:'',ic:''}}      // the epic that is set: its name and its icon (when it has one yet)
