  const sh=s=>s.str/s.hp,med=seq.map(sh).sort((x,y)=>x-y)[seq.length>>1],weak=s=>sh(s)<0.8*med||s.name=='Grace',hunt=s=>s.cat=='Epic Monster Hunter'&&!weak(s);
