  const mainSeq=grp.flatMap(g=>g.l.sort((x,y)=>seq.indexOf(x)-seq.indexOf(y))),head=[...mainSeq,...seq.filter(hunt)],wkA=seq.filter(s=>weak(s)&&s.name!='Grace'),wkG=seq.filter(s=>s.name=='Grace'),chain=[...head,...wkA,...wkG];
