const TPLW2={G:{Melee:[.0880,.0035],Mounted:[.0794,.0044],Ranged:[.1010,.0052],Flying:[.1049,.0080]},S:{Melee:[.1127,.0342],Mounted:[.0984,.0366],Ranged:[.1355,.0378],Flying:[.1008,.0496]},M:{Melee:[.2201,.0382],Flying:[.2007,.0265],Mounted:[.2298,.0440],Ranged:[.2043,.0363]}};
function template2(names){const tiers=[...new Set(names.map(n=>TRN[n].tier))].sort((a,b)=>b-a);return names.map(n=>{const t=TRN[n],r=tiers.indexOf(t.tier),row=TPLW2[t.cls]&&TPLW2[t.cls][t.cat];if(!row)return 0.05;return r<2?row[r]:row[1]*0.5})}
