function openTierCheck(){HINTGEN++;$('tcm').hidden=false;$('tcb').innerHTML='<p data-w=1>Checking the tiers...</p>';$('tcx').focus();tierHint(HINTGEN)}
function closeTierCheck(){HINTGEN++;$('tcm').hidden=true}
let TCC=null;      // 20.4.2: the last finished Tier check {sig, node}: with the same inputs and tiers the button only shows / hides it again, no new run
const tcSig=()=>{const d=snap();return JSON.stringify([d.vals,d.chk,d.atk,d.mode,d.enemy])};
function tierBubble(){      // 19.1: the Tier check result is shown in a bubble under the tiers
  const a=$('tca');if(!a)return;const sig=tcSig();
  if(TCC&&TCC.sig===sig){if(a.dataset.open=='1'){closeBubble()}else{a.dataset.open='1';tcOn(1);a.innerHTML='';a.appendChild(TCC.node)}return}      // nothing changed since the finished check: hide / show it
  TCC=null;a.dataset.open='1';a.innerHTML='<p class="mu" data-w=1>Checking the tiers...</p>';tcOn(1);const g=++HINTGEN;
  const b=document.createElement('div');b.className='tcb2';a.innerHTML='';a.appendChild(b);b.innerHTML='<p class="mu" data-w=1>Checking the tiers...</p>';
  tierHint(g,b).then(()=>{if(g===HINTGEN&&!b.querySelector('[data-w]'))TCC={sig,node:b}}).catch(()=>{})}
const tcOn=on=>document.querySelectorAll('.tcw .tc').forEach(b=>{b.classList.toggle('on',!!on);b.setAttribute('aria-pressed',on?'true':'false')});      // 20.4.3: the Tier check button is lit while its bubble is open (checking or showing the result)
function closeBubble(){HINTGEN++;const a=$('tca');if(a){a.dataset.open='0';a.innerHTML=''}tcOn(0)}
$('tcx').addEventListener('click',closeTierCheck);$('tcm').addEventListener('click',e=>{if(e.target===$('tcm'))closeTierCheck()});
document.addEventListener('keydown',e=>{if(e.key=='Escape'&&!$('tcm').hidden)closeTierCheck()});
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('.ob');if(!b)return;OVK=OVK===b.dataset.o?null:b.dataset.o;drawBR()});      // a click on the open button closes its list, a click on another one switches
// ---- Help sections (v292): every card with data-help gets a Help button in its header (hidden panel, same design on every card).
// The text (HTML allowed; t = the list of tips, each one a paragraph of its own that starts with the star marker) and the screenshots live HERE and nowhere else. img: a list of {src, alt, cap}; src is a data: URI (the page is a single file) or a file path.
const HELP={
  army:{t:["Don't have mercenaries at all? Keep Authority at 0, it has no use for you. Have a little bit of mercenaries? Just input less Authority than you actually have, check the given stacks and adjust if needed.","Lack of monster coins, so you want to use smaller monster stacks? Just input less Dominance than you actually have, check the given stacks and adjust if needed."],img:[]},
  food:{t:["<b>Food prod.</b> is the total food production you can use to train army. It has no effect on the stacks, but it enables the Preparation action, which shows how many units you can train per stack at once to achieve the maximum hit per training.","The <b>Revive</b> selection is used together with Food prod. to calculate the number of units you can train per stack.","The app assumes you have the 25 % food consumption reduction bonus active.","<b>Temple</b> is your Temple level (0-45; 45 is the highest, 0 = no Temple). The Result summary shows the <b>revive cost</b> in gold as <b>selected / full</b>: the gold to revive the stacks that the Revive select brings back, and the gold of a full revive of the whole hit."],img:[]},
  bonx:{t:["Bonus against epic monsters can be found by clicking on a troop in the battle report or in the city.","When checking the bonus in the city, have only the attacking captain/captains/hero in the city, with the equipment that goes into the battle on them."],tp:["Bonuses against players can be found by clicking on a troop in the battle report or in the city.","When checking the bonuses in the city, have only the attacking captain/captains/hero in the city, with the equipment that goes into the battle on them."],img:[]},      // 13.10: tp = the text of the Attack players view (t is the Attack epics one); calc switches the panel
  bon:{t:["The <b>Health</b> and <b>Strength</b> bonuses of each troop category (Guardsmen, Specialists, Monsters and Siege Engines) can be found by clicking on a troop in the battle report or in the city.","When checking the bonuses in the city, have only the attacking captain/captains/hero in the city, with the equipment that goes into the battle on them.","Do not check the Guardsmen/Specialists bonuses on troops that are both Guardsmen/Specialists and Beasts: the flying G5-G7 and S8-S9."],img:[]},
  mb:{t:["Monster boost research in the Academy has 3 parts. Click I, II or III based on the latest research part you have already finished. For a partially finished part, e.g. no research is done for health at part III, still click III and adjust the health manually to 50."],img:[]},
  rare:{t:["These should be rarely used bonuses. More often than not you don't need to input anything and can leave them at 0.","Category bonus Double damage comes only from <b>standard equipment</b> that can be crafted for Guardsmen, Specialists or Engineers.","Combatless Guardsmen mercenaries (Guardsmen mercenaries that are not Melee, Ranged, Mounted or Flying, such as the Epic Monster Hunter and the Elder Witch) use only their own bonus in Special troop type bonuses, not the Guardsmen bonus. Scouts (a Specialists unit type) likewise use only their own bonus, not the Specialists bonus.","Combat type bonuses: use these only if a specific category or type has a bonus on top of the class bonus above \u2014 e.g. unbalanced research, talents, or captain effects. Leave all on 0% if there are no imbalances."],tp:["These should be rarely used bonuses. More often than not you don't need to input anything and can leave them at 0.","Category bonus Strength against players comes only from <b>tournament equipment</b> that can be crafted for Guardsmen or Specialists.","Combatless Guardsmen mercenaries (Guardsmen mercenaries that are not Melee, Ranged, Mounted or Flying, such as the Epic Monster Hunter and the Elder Witch) use only their own bonus in Special troop type bonuses, not the Guardsmen bonus. Scouts (a Specialists unit type) likewise use only their own bonus, not the Specialists bonus.","Combat type bonuses: use these only if a specific category or type has a bonus on top of the class bonus above \u2014 e.g. unbalanced research, talents, or captain effects. Leave all on 0% if there are no imbalances."],img:[]},      // 19.0.107: tp = the text of the Attack players view (the Rare bonuses card follows the view like Army bonuses)
  sb:{t:["Use these only if a specific category or type has a bonus on top of the class bonus above \u2014 e.g. unbalanced research, talents, or captain effects. Leave all on 0% if there are no imbalances."],img:[]},
  tiers:{t:["Tick the tiers of every troop type you want the calculation to use. Tiers you don't have, or don't want to send, stay unticked.","Click <b>Tier check</b> under the tiers to see potential suggestions for improvement in a bubble below."],img:[]},
  mode:{t:["Choose the mode based on the hits you are planning to do most of the time."],img:[]},
  res:{t:["Click a troop card to turn it on or off.","Check the battle report and compare it with your in-game report, there should not be any difference except some rounding errors. If there is significant difference, either in hit/die order or the numbers, your inputs / bonuses are probably not correct, double check or ask for help.","The battle report does not display double damage hits and double strike, so these differences are normal to see, they are random, so can't be shown deterministically.","The battle report shows only one scenario, the one where you attack first. It is a 50/50 chance who attacks first, but the only change in the other scenario is the swap of the first couple of lines in round 1, until the enemy stops hitting."],img:[]}
};
function helpHtml(h,pl){return(pl&&h.tp?h.tp:h.t).map(x=>'<p class="ht"><i class="hm"></i>'+x+'</p>').join('')+(h.img||[]).map(m=>'<figure><img src="'+m.src+'" alt="'+(m.alt||'')+'" loading="lazy">'+(m.cap?'<figcaption>'+m.cap+'</figcaption>':'')+'</figure>').join('')}      // the tips of a Help panel as HTML; pl = the Attack players view (only the Bonuses against enemies card has its own text for it)
(function(){
  document.querySelectorAll('[data-help]').forEach(card=>{
    const k=card.dataset.help,h=HELP[k],head=[...card.children].find(x=>x.tagName=='H2'||x.tagName=='SUMMARY');if(!h||!head)return;
    const id='hp-'+k,b=document.createElement('button');b.type='button';b.className='hq';b.setAttribute('aria-expanded','false');b.setAttribute('aria-controls',id);b.title='Show help';b.setAttribute('aria-label','Help');b.innerHTML='?';head.appendChild(b);
    const p=document.createElement('div');p.className='hp';p.id=id;p.hidden=true;
    p.innerHTML=helpHtml(h,(k=='bonx'||k=='rare')&&ATK=='players');
    head.after(p);
  });
  document.addEventListener('click',e=>{
    const b=e.target.closest('.hq');if(!b)return;
    e.preventDefault();                                   // a Help button inside a summary must not open / close the card
    const p=document.getElementById(b.getAttribute('aria-controls')),open=p.hidden;p.hidden=!open;if(open){const d=b.closest('details');if(d)d.open=true}      // showing the help of a closed (collapsible) card opens the card too
    b.setAttribute('aria-expanded',String(open));b.title=open?'Hide help':'Show help';
    if(b.closest('[data-help=rare]')){try{localStorage.setItem('sc_rarehelp',open?'1':'0')}catch(x){}}      // 20.1.1: the Rare bonuses help remembers how the user left it
  });
  document.querySelectorAll('details[data-help]').forEach(d=>{const sync=()=>{const b=d.querySelector('.hq'),p=b&&document.getElementById(b.getAttribute('aria-controls'));if(b&&p)b.setAttribute('aria-expanded',String(d.open&&!p.hidden))};d.addEventListener('toggle',()=>setTimeout(sync,0))});      // 20.1.2: a closed section does not show its help button lit
  {const rc=document.querySelector('details[data-help=rare]');      // 20.1.1: opening the Rare bonuses card shows its help, unless the user closed it last time
    if(rc)rc.addEventListener('toggle',()=>{if(!rc.open)return;let pr='1';try{pr=localStorage.getItem('sc_rarehelp')||'1'}catch(x){}const p=$('hp-rare'),b=rc.querySelector('.hq');if(pr=='1'&&p&&p.hidden){p.hidden=false;if(b){b.setAttribute('aria-expanded','true');b.title='Hide help'}}})}
})();
document.addEventListener('input',e=>{const t=e.target;if(t.classList&&t.classList.contains('tabin'))return;if(!(t.matches&&t.matches(NUMBOX)))return;fmtBox(t);clearTimeout(CALCT);clearTimeout(SAVET);if(t.value.trim()===''){CALCT=0;SAVET=setTimeout(save,400);return}CALCT=setTimeout(calc,Math.min(1200,Math.max(500,4*CALCMS)))});      // ANY change of a number box (typing, Backspace, cut, paste, drop ...): the number is formatted at once, the calculation waits until the typing has stopped (0.5 s, longer on a slow device); an emptied box starts nothing (a new number is coming)
// A number box that holds 0 empties when you click into it (a grey 0 stays as the hint), so only your own digits end up in it. Leave it without typing and the 0 comes back; the same when you type and then erase everything.
document.addEventListener('focusin',e=>{const t=e.target;if(!(t.matches&&t.matches(NUMBOX)))return;t._typed=false;if(t.value!==''&&parseFloat(String(t.value).replace(/,/g,''))===0){t.placeholder='0';t.value=''}});
document.addEventListener('input',e=>{if(e.target.matches&&e.target.matches(NUMBOX))e.target._typed=true});
document.addEventListener('focusout',e=>{const t=e.target;if(!(t.matches&&t.matches(NUMBOX)))return;if(t.value.trim()===''){t.value='0';if(t._typed){clearTimeout(CALCT);calc()}}t._typed=false});
document.addEventListener('change',e=>{if(e.target.classList&&e.target.classList.contains('tabin'))return;if(e.target.id=='xfile'){const f=e.target.files&&e.target.files[0];e.target.value='';if(f)xShot(f);return}if(e.target.id=='xt')return;if(e.target.type=='checkbox')refresh();else calc()});      // leaving a box (or a tick, a list) calculates at once
document.addEventListener('keydown',e=>{if(e.key=='Enter'&&e.target.matches&&e.target.matches(NUMBOX)){e.preventDefault();calc()}});      // Enter in a number box = calculate now, without waiting
